USE customer_shopping_db;
## Q1. What is the total revenue generated by male vs. female customers?
## Q2. Which customers used a discount but still spent more than the average purchase amount? 
## Q3. Which are the top 5 products with the highest average review rating?
## Q4. Compare the average Purchase Amounts between Standard and Express Shipping. 
## Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers
## Q6. Which 5 products have the highest percentage of purchases with discounts applied?
## Q7. Segment customers into New, Returning, and Loyal based on their total 
-- number of previous purchases, and show the count of each segment.
## Q8. What are the top 3 most purchased products within each category? 
## Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
## Q10. What is the revenue contribution of each age group? 
##!1
SELECT gender,SUM(purchase_amount) as revenue
FROM customer_shopping
GROUP BY gender;
##2
SELECT customer_id,purchase_amount
FROM customer_shopping
WHERE discount_applied = 'Yes' AND purchase_amount >= (SELECT AVG(purchase_amount) FROM customer_shopping);
##3
SELECT item_purchased,ROUND(AVG(review_rating),2) avg_product_rating
FROM customer_shopping
GROUP BY item_purchased
ORDER BY avg_rating desc
LIMIT 5;
##4
SELECT shipping_type,ROUND(AVG(purchase_amount),2) avg_purchase_amount
FROM customer_shopping
WHERE shipping_type in ('Standard','Express')
GROUP BY shipping_type;
##5
SELECT subscription_status,COUNT(customer_id) Total_No_of_customers,Sum(purchase_amount) revenue,ROUND(AVG(purchase_amount),2) Avg_purchased_amount
FROM customer_shopping
GROUP BY subscription_status;
##6
SELECT item_purchased,ROUND(100*SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END)/COUNT(*),2) discount_rate
FROM customer_shopping
GROUP BY item_purchased
ORDER BY discount_rate desc
LIMIT 5;
##7
SELECT CASE WHEN previous_purchases = 1 THEN 'New'
			WHEN previous_purchases between 2 and 10 THEN 'Returning'
            ELSE 'Loyal'
		END customer_segment,COUNT(customer_id) customer_count
FROM customer_shopping
GROUP BY customer_segment;
##8
WITH sub as
( SELECT category,item_purchased,COUNT(*) item_count,ROW_NUMBER() OVER(PARTITION BY category ORDER BY COUNT(customer_id) DESC) ITEM_rnk
  FROM customer_shopping
  GROUP BY category,item_purchased)
Select category,item_purchased,item_count
FROM sub
WHERE ITEM_rnk <= 3
ORDER BY category;
##9
SELECT subscription_status,COUNT(customer_id) repeat_buyers
FROM customer_shopping
WHERE previous_purchases > 5
GROUP BY subscription_status;
##10
SELECT age_group,SUM(purchase_amount) Total_Revenue
FROM customer_shopping
GROUP BY age_group
ORDER BY age_group;




